    "noEndpointsMessage": { "t": 0, "b": { "t": 2, "i": [{ "t": 3 }], "s": "\u0416\u043E\u0434\u043D\u0438\u0445 \u043A\u0456\u043D\u0446\u0435\u0432\u0438\u0445 \u0442\u043E\u0447\u043E\u043A \u0441\u0435\u0440\u0432\u0435\u0440\u0430 MCP (Model Context Protocol) \u043D\u0435 \u0434\u043E\u0434\u0430\u043D\u043E. \u0407\u0445 \u043C\u043E\u0436\u043D\u0430 \u0432\u0438\u043A\u043E\u0440\u0438\u0441\u0442\u043E\u0432\u0443\u0432\u0430\u0442\u0438 \u0434\u043B\u044F \u043F\u0440\u044F\u043C\u043E\u0457 \u0456\u043D\u0442\u0435\u0433\u0440\u0430\u0446\u0456\u0457 \u0437 LLM, \u043D\u0430\u043F\u0440\u0438\u043A\u043B\u0430\u0434 Claude, \u0449\u043E\u0431 \u043C\u043E\u0434\u0435\u043B\u044C \u043C\u043E\u0433\u043B\u0430 \u0432\u0438\u043A\u043E\u043D\u0443\u0432\u0430\u0442\u0438 \u0434\u0456\u0457 \u0431\u0435\u0437\u043F\u043E\u0441\u0435\u0440\u0435\u0434\u043D\u044C\u043E \u0432 Baserow. \u0421\u0442\u0432\u043E\u0440\u0456\u0442\u044C \u043A\u0456\u043D\u0446\u0435\u0432\u0443 \u0442\u043E\u0447\u043A\u0443 \u0441\u0435\u0440\u0432\u0435\u0440\u0430, \u0449\u043E\u0431 \u0440\u043E\u0437\u043F\u043E\u0447\u0430\u0442\u0438." } }
