    "warning": { "t": 0, "b": { "t": 2, "i": [{ "t": 3 }], "s": "\u0421\u0442\u0430\u0432\u0442\u0435\u0441\u044F \u0434\u043E \u0441\u0432\u043E\u0433\u043E URL MCP \u044F\u043A \u0434\u043E \u043F\u0430\u0440\u043E\u043B\u044F, \u043E\u0441\u043A\u0456\u043B\u044C\u043A\u0438 \u0432\u0456\u043D \u0434\u0430\u0454 \u043C\u043E\u0436\u043B\u0438\u0432\u0456\u0441\u0442\u044C \u0437\u043C\u0456\u043D\u044E\u0432\u0430\u0442\u0438 \u0434\u0430\u043D\u0456 \u0432 Baserow." } },
    "claudeInstructions": { "t": 0, "b": { "t": 2, "i": [{ "t": 3 }], "s": "\u0422\u0440\u0438 \u043F\u0440\u043E\u0441\u0442\u0456 \u043A\u0440\u043E\u043A\u0438, \u0449\u043E\u0431 \u0440\u043E\u0437\u043F\u043E\u0447\u0430\u0442\u0438 \u0440\u043E\u0431\u043E\u0442\u0443 \u0437 Claude Desktop \u0456 Baserow MCP.\n\n1. \u0412\u0456\u0434\u043A\u0440\u0438\u0439\u0442\u0435 \u043D\u0430\u043B\u0430\u0448\u0442\u0443\u0432\u0430\u043D\u043D\u044F Claude Desktop \u0447\u0435\u0440\u0435\u0437 \u043F\u0430\u043D\u0435\u043B\u044C \u043D\u0430\u0432\u0456\u0433\u0430\u0446\u0456\u0457. (\u2318+,)\n2. \u041F\u0435\u0440\u0435\u0439\u0434\u0456\u0442\u044C \u043D\u0430 \u0432\u043A\u043B\u0430\u0434\u043A\u0443 \xAB\u0420\u043E\u0437\u0440\u043E\u0431\u043A\u0430\xBB \u0456 \u043D\u0430\u0442\u0438\u0441\u043D\u0456\u0442\u044C \xAB\u0420\u0435\u0434\u0430\u0433\u0443\u0432\u0430\u0442\u0438 \u043A\u043E\u043D\u0444\u0456\u0433\u0443\u0440\u0430\u0446\u0456\u044E\xBB.\n3. \u0414\u043E\u0434\u0430\u0439\u0442\u0435 \u043D\u0430\u0441\u0442\u0443\u043F\u043D\u0443 JSON-\u043A\u043E\u043D\u0444\u0456\u0433\u0443\u0440\u0430\u0446\u0456\u044E \u0434\u043E \u0444\u0430\u0439\u043B\u0443 `claude_desktop_config.json`." } },
    "cursorInstructions": { "t": 0, "b": { "t": 2, "i": [{ "t": 3 }], "s": "\u0422\u0440\u0438 \u043F\u0440\u043E\u0441\u0442\u0456 \u043A\u0440\u043E\u043A\u0438, \u0449\u043E\u0431 \u0440\u043E\u0437\u043F\u043E\u0447\u0430\u0442\u0438 \u0440\u043E\u0431\u043E\u0442\u0443 \u0437 Cursor \u0456 Baserow MCP.\n\n1. \u0412\u0456\u0434\u043A\u0440\u0438\u0439\u0442\u0435 \u043D\u0430\u043B\u0430\u0448\u0442\u0443\u0432\u0430\u043D\u043D\u044F Cursor (\u21E7+\u2318+J)\n2. \u041F\u0435\u0440\u0435\u0439\u0434\u0456\u0442\u044C \u043D\u0430 \u0432\u043A\u043B\u0430\u0434\u043A\u0443 \xABMCP\xBB \u0456 \u043D\u0430\u0442\u0438\u0441\u043D\u0456\u0442\u044C \xAB\u0414\u043E\u0434\u0430\u0442\u0438 MCP-\u0441\u0435\u0440\u0432\u0435\u0440\xBB\n3. \u0414\u043E\u0434\u0430\u0439\u0442\u0435 \u043D\u0430\u0441\u0442\u0443\u043F\u043D\u0443 JSON-\u043A\u043E\u043D\u0444\u0456\u0433\u0443\u0440\u0430\u0446\u0456\u044E." } },
    "windsurfInstructions": { "t": 0, "b": { "t": 2, "i": [{ "t": 3 }], "s": "\u0414\u0432\u0430 \u043F\u0440\u043E\u0441\u0442\u0456 \u043A\u0440\u043E\u043A\u0438, \u0449\u043E\u0431 \u043D\u0430\u043B\u0430\u0448\u0442\u0443\u0432\u0430\u0442\u0438 MCP \u0437 Cascade \u0443 Windsurf.\n\n1. \u041F\u0435\u0440\u0435\u0439\u0434\u0456\u0442\u044C \u0434\u043E Windsurf \u2192 Settings \u2192 Advanced Settings \u0430\u0431\u043E \u0432\u0456\u0434\u043A\u0440\u0438\u0439\u0442\u0435 Command Palette \u2192 Open Windsurf settings page.\n2. \u041F\u0440\u043E\u043A\u0440\u0443\u0442\u0456\u0442\u044C \u0434\u043E \u0440\u043E\u0437\u0434\u0456\u043B\u0443 Cascade \u2014 \u0442\u0430\u043C \u0432\u0438 \u0437\u043D\u0430\u0439\u0434\u0435\u0442\u0435 \u043C\u043E\u0436\u043B\u0438\u0432\u0456\u0441\u0442\u044C \u0434\u043E\u0434\u0430\u0442\u0438 \u043D\u043E\u0432\u0438\u0439 \u0441\u0435\u0440\u0432\u0435\u0440, \u043F\u0435\u0440\u0435\u0433\u043B\u044F\u043D\u0443\u0442\u0438 \u043D\u0430\u044F\u0432\u043D\u0456 \u0441\u0435\u0440\u0432\u0435\u0440\u0438 \u0442\u0430 \u043A\u043D\u043E\u043F\u043A\u0443 \u0434\u043B\u044F \u043F\u0435\u0440\u0435\u0433\u043B\u044F\u0434\u0443 \u0441\u0438\u0440\u043E\u0433\u043E JSON-\u0444\u0430\u0439\u043B\u0443 \u043A\u043E\u043D\u0444\u0456\u0433\u0443\u0440\u0430\u0446\u0456\u0457 mcp_config.json. \u0414\u043E\u0434\u0430\u0439\u0442\u0435 \u0434\u043E \u043D\u044C\u043E\u0433\u043E \u0442\u0430\u043A\u0435:" } }
